  assert.equal(r.SPIt, 7.5 / 7);
  // everything verified: EV 180 = PVd(13), no day 14 → ES = 13
  const all = ['a', 'b', 'c', 'd'].map((c) => E(c, 'pass', '2026-01-02'));
  r = earned(evReqs, evLinks, all, plan, [], { asOf: '2026-01-04' });
