projects/p-tape1/fakesd.mjs:
// fakesd.mjs — the lab's SD card and flash as SPEC describes them, for our tests. (Modulo, tape day 1)
//
// makeSD(files = {}, { cutAt }) : files is { path: text }; folders are implied by paths, and
// `dirs` may list empty ones. Every mutating call is one step (sd.steps counts them). When
// sd.cutAt === sd.steps at a call, power fails there: write/append leave the first half
// (floor(len/2)) of their text, rename/remove do nothing, and the call throws PowerCut.
// list() returns names in an order scrambled by a seed, because the spec promises no order.
export class PowerCut extends Error { constructor() { super('power cut'); this.name = 'PowerCut'; } }

export function makeSD(files = {}, { dirs = [], cutAt = -1, seed = 7 } = {}) {
  const f = new Map(Object.entries(files));
  const d = new Set(dirs);
  let s = seed >>> 0;
  const rnd = () => ((s = (s * 1664525 + 1013904223) >>> 0) / 2 ** 32);
  const norm = (p) => p.replace(/\/+$/, '');
  const isDir = (p) => { p = norm(p); if (d.has(p)) return true; for (const k of f.keys()) if (k.startsWith(p + '/')) return true; for (const k of d) if (k.startsWith(p + '/')) return true; return false; };
  const sd = {
    files: f, steps: 0, cutAt,
    _step() { const n = sd.steps++; if (n === sd.cutAt) return true; return false; },
    list(dir) {
      dir = norm(dir); const out = new Set();
      for (const k of [...f.keys(), ...d]) if (k.startsWith(dir + '/')) out.add(k.slice(dir.length + 1).split('/')[0]);
      const a = [...out];
      for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
      return a;
    },
    isDir,
    read(p) { return f.has(p) ? f.get(p) : null; },
    write(p, text) { if (sd._step()) { f.set(p, text.slice(0, Math.floor(text.length / 2))); throw new PowerCut(); } f.set(p, text); },
    append(p, text) { const old = f.get(p) ?? ''; if (sd._step()) { f.set(p, old + text.slice(0, Math.floor(text.length / 2))); throw new PowerCut(); } f.set(p, old + text); },
    rename(a, b) { if (sd._step()) throw new PowerCut(); if (!f.has(a)) throw new Error('ENOENT ' + a); f.set(b, f.get(a)); f.delete(a); },
    remove(p) { if (sd._step()) throw new PowerCut(); f.delete(p); },
  };
  return sd;
}

export function makeFlash(value = null) {
  let v = value === null ? null : JSON.parse(JSON.stringify(value));
  return { get: () => (v === null ? null : JSON.parse(JSON.stringify(v))), set: (x) => { v = JSON.parse(JSON.stringify(x)); } };
}

projects/p-tape1/fresh.mjs:
// fresh.mjs — evidence that knows what it was evidence about. (Modulo, day 1)
//
// stamp(entry, links, readFile)      → { ...entry, digests: { [artifactPath]: sha256hex | null } }
// filter(evidence, links, readFile)  → the entries whose recorded digests all still match
//
// An entry names its check (`entry.check`). links say which requirements a check `verifies` and
// which artifacts `implements` each requirement. The digests cover every artifact implementing any
// requirement the check verifies; change one byte of one and exactly those entries drop out.
//
// LINK SHAPE: tools/vv/ was NOT in the folder on day 1, so vv's own links format is unknown. links()
// below accepts the shapes we could guess, and every other function goes through it, so when vv
// arrives this is the one place to fix:
//   [{ from, rel|type|kind, to }]                         (our links.json uses this)
//   { links: [...same...] }
//   { implements: [[artifact, req], ...] | [{from,to}], verifies: [[check, req], ...] }
//
// DECISIONS:
//  F-a  An entry with no `digests` was never stamped: filter drops it (nothing vouches for it).
//       An entry whose check verifies nothing, or whose requirements have no implementing artifact,
//       stamps `digests: {}` and is kept: there is nothing it could go stale against.
//  F-b  An artifact that can't be read stamps as null, and null never matches, not even null:
//       evidence about a file that isn't there can't stand.
//  F-c  readFile may return a string (hashed as UTF-8) or bytes.
//  F-d  filter judges each entry against the links as they are now (Morphyx, day 2). A requirement
//       that gains an implementing file drops the evidence stamped before it (that file was never
//       hashed); a file that stops implementing stops counting. Day 1 checked recorded digests only,
//       so evidence outlived a change in what it was evidence about.
import { createHash } from 'node:crypto';

function norm(l) {
  return { from: l.from ?? l.source ?? l.src, rel: l.rel ?? l.type ?? l.kind, to: l.to ?? l.target ?? l.dst };
}
export function linksOf(links) {
  if (Array.isArray(links)) return links.map(norm);
  if (links && Array.isArray(links.links)) return links.links.map(norm);
  const out = [];
  for (const rel of ['implements', 'verifies']) {
    for (const x of (links && links[rel]) || []) {
      out.push(Array.isArray(x) ? { from: x[0], rel, to: x[1] } : { ...norm(x), rel });
    }
  }
  return out;
}

export function artifactsFor(check, links) {
  const ls = linksOf(links);
  const reqs = new Set(ls.filter((l) => l.rel === 'verifies' && l.from === check).map((l) => l.to));
  return [...new Set(ls.filter((l) => l.rel === 'implements' && reqs.has(l.to)).map((l) => l.from))].sort();
}

function digest(path, readFile) {
  let data;
  try { data = readFile(path); } catch { return null; }
  if (data == null) return null;
  return createHash('sha256').update(typeof data === 'string' ? Buffer.from(data, 'utf8') : data).digest('hex');
}

export function stamp(entry, links, readFile) {
  const digests = {};
  for (const p of artifactsFor(entry.check, links)) digests[p] = digest(p, readFile);
  return { ...entry, digests };
}

export function filter(evidence, links, readFile) {
  const cache = new Map();
  const now = (p) => { if (!cache.has(p)) cache.set(p, digest(p, readFile)); return cache.get(p); };
  return evidence.filter((e) => {
    if (!e || !e.digests || typeof e.digests !== 'object') return false;
    // F-d: judge against what the links say *now*. A file linked since the stamp was never hashed,
    // so nothing vouches for it: drop. A file unlinked since no longer bears on the check: ignore it.
    return artifactsFor(e.check, links).every((p) => Object.hasOwn(e.digests, p) && e.digests[p] !== null && now(p) === e.digests[p]);
  });
}

projects/p-tape1/harness-rr.mjs:
// harness-rr.mjs (carried from Stopwatch unchanged; encode/decode live in harness.mjs) — record a model live (fake clock), replay it simulated, compare decisions. (Modulo, day 1)
//
// record(model, { seed, until, scale = 1, injections = [] }) → Promise<log>
// replay(model, log, { seed, until })                        → Promise<{ ok, mismatches }>
//
// The model is `model(sim)`; it calls `sim.decide(kind, data)` for every decision. The log is
// [{ t, kind, data }] in the order things happened, injections included as kind 'inject',
// data { name, value }.
//
// DECISIONS (see README "Harness decisions"):
//  H-a  A decision matches when t, kind and data are equal (data compared as canonical JSON:
//       key order ignored, -0 = 0, NaN/Infinity kept distinct as strings).
//  H-b  Math.random is a tripwire, not only a source of divergence. While a model runs (record or
//       replay) Math.random still returns real randoms but every call is counted. replay reports
//       a mismatch { index, expected: 'no Math.random', got: 'Math.random called' } at the index of
//       the first decision not yet made when it was first called. Divergence alone would miss
//       `Math.random() < 2`. Restored in finally. (Date.now is not trapped: it can't change a
//       decision unless something reads it, and a fake-clock model has no reason to.)
//  H-c  An injection whose time comes before the clock first sleeps (at ≤ 0) is injected just
//       before runRealtime starts. One whose time never arrives (the run ended first) is not
//       delivered and not logged: the log holds what happened, not what was planned.
//  H-d  In replay an injection is fed at its logged sim time t (the time des actually delivered
//       it, max(now, clock/scale)) in the same queue position record gave it: run every step
//       strictly before t, set now = t, sim.inject. (Day 1 pre-scheduled a step at t instead; an
//       entry the model queued at t during setup then ran before the injection in replay and after
//       it in record. Morphyx, day 2: test h1-tie-order.)
import { Sim } from './tools/des/des.mjs';

function canon(v) {
  if (typeof v === 'number') return Object.is(v, -0) ? 0 : Number.isFinite(v) ? v : String(v);
  if (v === undefined) return '__undefined__';
  if (Array.isArray(v)) return v.map(canon);
  if (v && typeof v === 'object') {
    const o = {};
    for (const k of Object.keys(v).sort()) o[k] = canon(v[k]);
    return o;
  }
  return v;
}
// the largest double below t (t finite, > -Infinity)
function below(t) {
  if (t === 0) return -Number.MIN_VALUE;
  const b = new DataView(new ArrayBuffer(8)); b.setFloat64(0, t);
  b.setBigInt64(0, b.getBigInt64(0) + (t > 0 ? -1n : 1n));
  return b.getFloat64(0);
}
const same = (a, b) => JSON.stringify(canon(a)) === JSON.stringify(canon(b));

// count Math.random calls during fn; returns [result, firstCallDecisionIndex | -1]
async function trapped(fn, decisionsSoFar) {
  const real = Math.random;
  let first = -1;
  Math.random = function random() { if (first < 0) first = decisionsSoFar(); return real(); };
  try { return [await fn(), first]; } finally { Math.random = real; }
}

export async function record(model, { seed = 1, until, scale = 1, injections = [] } = {}) {
  if (!(scale > 0)) throw new RangeError('scale must be > 0');
  const log = [];
  let ms = 0;                                   // the fake clock: moves only when slept
  const pending = [...injections].map((x, i) => ({ ...x, i }))
    .sort((a, b) => a.at - b.at || a.i - b.i);
  let sim;
  const deliver = (inj) => {
    const t = sim._rt ? Math.max(sim.now, ms / scale) : sim.now;
    log.push({ t, kind: 'inject', data: { name: inj.name, value: inj.value } });
    sim.inject(inj.name, inj.value);
  };
  const clock = {
    now: () => ms,
    sleep: async (d) => {
      const target = ms + d;
      // wake at the first injection inside this sleep; des re-checks its queue after any wake
      if (pending.length && pending[0].at * scale <= target) {
        ms = Math.max(ms, pending[0].at * scale);
        while (pending.length && pending[0].at * scale <= ms) deliver(pending.shift());
      } else ms = target;
    },
  };
  sim = new Sim({ seed, clock });
  sim.decide = (kind, data) => { log.push({ t: sim.now, kind, data }); };
  const [, first] = await trapped(async () => {
    model(sim);
    while (pending.length && pending[0].at <= 0) deliver(pending.shift());
    await sim.runRealtime(until === undefined ? { scale } : { until, scale });
  }, () => 0);
  if (first >= 0) Object.defineProperty(log, 'mathRandom', { value: true }); // visible to callers, not serialised
  return log;
}

export async function replay(model, log, { seed = 1, until } = {}) {
  const expected = log.filter((e) => e.kind !== 'inject');
  const got = [];
  const sim = new Sim({ seed });
  sim.decide = (kind, data) => { got.push({ t: sim.now, kind, data }); };
  const [, first] = await trapped(() => {
    model(sim);
    // H-d: deliver each injection the way record does: once every step strictly before its t has
    // run, and before any step at t, so it joins the queue behind what is already waiting at t and
    // ahead of what steps at t create.
    const end = until === undefined ? Infinity : until;
    for (const e of log) {
      if (e.kind !== 'inject') continue;
      const t = Math.max(e.t, sim.now);
      if (t > end) break;                       // record never delivers past until
      const before = below(t);
      if (before >= sim.now) sim.run({ until: before });
      sim.now = t;                              // nothing is queued in (before, t): floats have no room
      sim.inject(e.data.name, e.data.value);
    }
    sim.run(until === undefined ? {} : { until });
  }, () => got.length);
  const mismatches = [];
  if (first >= 0) mismatches.push({ index: first, expected: 'no Math.random', got: 'Math.random called' });
  const n = Math.max(expected.length, got.length);
  for (let i = 0; i < n; i++) {
    if (!same(expected[i], got[i])) mismatches.push({ index: i, expected: expected[i], got: got[i] });
  }
  return { ok: mismatches.length === 0, mismatches };
}

projects/p-tape1/harness.mjs:
// harness.mjs — Stopwatch's record/replay, carried across, plus encode/decode. (Modulo, tape day 1)
//
// encode(value) → string, decode(string) → value. Round-trips every JSON value and also NaN,
// ±Infinity, -0 and undefined, wherever they sit.
//
// DECISIONS:
//  H-tag  The encoding is JSON in which a *tag* is an object whose only key is "$":
//         {"$":"NaN"} {"$":"Infinity"} {"$":"-Infinity"} {"$":"-0"} {"$":"undefined"}.
//         A caller's own key that begins with "$" is written with one more "$" in front
//         ("$" → "$$", "$x" → "$$x"), so no caller object can ever look like a tag, however it is
//         built. Strings are never touched: tags are objects, so "NaN" stays a string.
//  H-abs  A field that is absent or undefined in an object stays absent (JSON's rule; the spec's).
//         undefined inside an array is kept as {"$":"undefined"} so the array's length and indices
//         survive. Top-level undefined round-trips too.
//  H-proto  Decoded objects get their keys with defineProperty, so a key "__proto__" is an own
//         field, never a prototype change.
//  fi-5f90c6: Stopwatch's canon() turned NaN into the string "NaN", so NaN and "NaN" compared
//         equal. Here they are different encodings, and the test checks it.
export { record, replay } from './harness-rr.mjs';

const TAG = '$';
const SPECIAL = { NaN, Infinity, '-Infinity': -Infinity, '-0': -0, undefined };

function enc(v, inArray) {
  if (typeof v === 'number') {
    if (Number.isNaN(v)) return { [TAG]: 'NaN' };
    if (v === Infinity) return { [TAG]: 'Infinity' };
    if (v === -Infinity) return { [TAG]: '-Infinity' };
    if (Object.is(v, -0)) return { [TAG]: '-0' };
    return v;
  }
  if (v === undefined) return { [TAG]: 'undefined' };
  if (v === null) return null;
  if (typeof v !== 'object') {
    if (typeof v === 'string' || typeof v === 'boolean') return v;
    throw new TypeError(`encode: not a JSON value (${typeof v})`);
  }
  if (typeof v.toJSON === 'function' && !Array.isArray(v)) return enc(v.toJSON(), inArray);
  if (Array.isArray(v)) return Array.from(v, (x) => enc(x, true));
  const o = {};
  for (const k of Object.keys(v)) {
    if (v[k] === undefined || typeof v[k] === 'function' || typeof v[k] === 'symbol') continue;
    Object.defineProperty(o, k.startsWith(TAG) ? TAG + k : k,
      { value: enc(v[k], false), enumerable: true, writable: true, configurable: true });
  }
  return o;
}

function dec(v) {
  if (Array.isArray(v)) return v.map(dec);
  if (v === null || typeof v !== 'object') return v;
  const keys = Object.keys(v);
  if (keys.length === 1 && keys[0] === TAG) {
    if (typeof v[TAG] === 'string' && Object.prototype.hasOwnProperty.call(SPECIAL, v[TAG])) return SPECIAL[v[TAG]];
    throw new SyntaxError(`decode: unknown tag ${JSON.stringify(v[TAG])}`);
  }
  const o = {};
  for (const k of keys) {
    Object.defineProperty(o, k.startsWith(TAG) ? k.slice(1) : k,
      { value: dec(v[k]), enumerable: true, writable: true, configurable: true });
  }
  return o;
}

export function encode(value) { return JSON.stringify(enc(value, false)); }
export function decode(text) { return dec(JSON.parse(text)); }

