  // ============================================================
  // 23. network graph (deterministic force layout, coloured by community)
  // ============================================================
  C.network = function (o) {
    var w = o.width || 350, h = o.height || 300, nodes = o.nodes, edges = o.edges;
    var m = { l: 12, r: 12, t: 12, b: 12 }, iw = w - m.l - m.r, ih = h - m.t - m.b;
