    var xs = nodes.map(function (nd) { return pos[nd.id].x; }), ys = nodes.map(function (nd) { return pos[nd.id].y; });
    var spanX = (ST.max(xs) - ST.min(xs)) || 1, spanY = (ST.max(ys) - ST.min(ys)) || 1;
