// Generates PERIODS back-to-back rotas of DAYS days and sums, per person, (shifts − share) and
// (weekend shifts − weekend share). Each period can pass POLICY.md while the same person loses
// a little every time; this shows it. Linear growth = a standing bias; ~sqrt(PERIODS) = noise.
import { makeRota } from '../lib/assign.mjs';
import { shares, tally, balance } from '../lib/policy.mjs';
import { days } from '../lib/calendar.mjs';
import { loadPeople } from '../lib/people.mjs';
const [file, start, n0, k0, ...flags] = process.argv.slice(2);
const flag = flags.includes('--no-leave') ? '--no-leave' : '', useCarry = flags.includes('--carry'), past = [];
const n = Number(n0), k = Number(k0), team = loadPeople(file);
if (flag === '--no-leave') for (const p of team) p.leave = new Set();
const acc = Object.fromEntries(team.map((p) => [p.name, [0, 0]]));
for (let i = 0, s = start; i < k; i++, s = days(s, n + 1).pop()) {
  const r = makeRota(team, s, n, { carry: useCarry ? balance(team, past) : null }); past.push(r);
  const t = tally(r), sh = shares(team, s, n);
  for (const p of team) { acc[p.name][0] += (t[p.name]?.total ?? 0) - sh.get(p.name).total; acc[p.name][1] += (t[p.name]?.weekend ?? 0) - sh.get(p.name).weekend; }
}
console.log(`${k} × ${n}-day periods from ${start}: cumulative shifts − share, weekend shifts − share`);
for (const [x, [a, b]] of Object.entries(acc)) console.log(`${x.padEnd(12)} ${a.toFixed(1).padStart(7)} ${b.toFixed(1).padStart(7)}`);

shelf/fakesd.mjs:
// fakesd.mjs — the lab's SD card and flash as SPEC describes them, for our tests. (Modulo, tape day 1)
//
// makeSD(files = {}, { cutAt }) : files is { path: text }; folders are implied by paths, and
// `dirs` may list empty ones. Every mutating call is one step (sd.steps counts them). When
// sd.cutAt === sd.steps at a call, power fails there: write/append leave the first half
// (floor(len/2)) of their text, rename/remove do nothing, and the call throws PowerCut.
// list() returns names in an order scrambled by a seed, because the spec promises no order.
export class PowerCut extends Error { constructor() { super('power cut'); this.name = 'PowerCut'; } }

export function makeSD(files = {}, { dirs = [], cutAt = -1, seed = 7 } = {}) {
  const f = new Map(Object.entries(files));
  const d = new Set(dirs);
  let s = seed >>> 0;
  const rnd = () => ((s = (s * 1664525 + 1013904223) >>> 0) / 2 ** 32);
  const norm = (p) => p.replace(/\/+$/, '');
  const isDir = (p) => { p = norm(p); if (d.has(p)) return true; for (const k of f.keys()) if (k.startsWith(p + '/')) return true; for (const k of d) if (k.startsWith(p + '/')) return true; return false; };
  const sd = {
    files: f, steps: 0, cutAt,
    _step() { const n = sd.steps++; if (n === sd.cutAt) return true; return false; },
    list(dir) {
      dir = norm(dir); const out = new Set();
      for (const k of [...f.keys(), ...d]) if (k.startsWith(dir + '/')) out.add(k.slice(dir.length + 1).split('/')[0]);
      const a = [...out];
      for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
      return a;
    },
    isDir,
    read(p) { return f.has(p) ? f.get(p) : null; },
    write(p, text) { if (sd._step()) { f.set(p, text.slice(0, Math.floor(text.length / 2))); throw new PowerCut(); } f.set(p, text); },
    append(p, text) { const old = f.get(p) ?? ''; if (sd._step()) { f.set(p, old + text.slice(0, Math.floor(text.length / 2))); throw new PowerCut(); } f.set(p, old + text); },
    rename(a, b) { if (sd._step()) throw new PowerCut(); if (!f.has(a)) throw new Error('ENOENT ' + a); f.set(b, f.get(a)); f.delete(a); },
    remove(p) { if (sd._step()) throw new PowerCut(); f.delete(p); },
  };
  return sd;
}

export function makeFlash(value = null) {
  let v = value === null ? null : JSON.parse(JSON.stringify(value));
  return { get: () => (v === null ? null : JSON.parse(JSON.stringify(v))), set: (x) => { v = JSON.parse(JSON.stringify(x)); } };
}

shelf/ledger.mjs:
#!/usr/bin/env node
// ledger.mjs — who carries a rota. Self-contained; reads any {"YYYY-MM-DD": [names...]} JSON.
//   node shelf/ledger.mjs rota.json [people.json]
// people.json (optional): [{name, fte, leave:[dates]}]. Weight = fte × days not on leave / DAYS,
// as in the clinic's POLICY.md; without it everyone named in the rota weighs 1.
// Prints per person: shifts vs weighted share, weekend shifts vs share, longest run of days on.
import { readFileSync } from 'node:fs';
const [rf, pf] = process.argv.slice(2);
const rota = JSON.parse(readFileSync(rf, 'utf8'));
const ds = Object.keys(rota).sort(), n = ds.length;
const wkd = (d) => [0, 6].includes(new Date(`${d}T00:00:00Z`).getUTCDay());
const people = pf ? JSON.parse(readFileSync(pf, 'utf8'))
  : [...new Set(Object.values(rota).flat())].map((name) => ({ name }));
const slots = ds.reduce((a, d) => a + rota[d].length, 0), wslots = ds.filter(wkd).reduce((a, d) => a + rota[d].length, 0);
const w = people.map((p) => (p.fte ?? 1) * ds.filter((d) => !(p.leave || []).includes(d)).length / n);
const W = w.reduce((a, b) => a + b, 0);
console.log('name        shifts  share   diff | wkend  share   diff | longest run');
people.forEach((p, i) => {
  const on = ds.map((d) => rota[d].includes(p.name));
  const t = on.filter(Boolean).length, we = ds.filter((d, j) => on[j] && wkd(d)).length;
  let run = 0, best = 0; for (const x of on) best = Math.max(best, (run = x ? run + 1 : 0));
  const s = slots * w[i] / W, sw = wslots * w[i] / W, f = (x) => x.toFixed(2).padStart(6);
  console.log(`${p.name.padEnd(10)} ${String(t).padStart(6)} ${f(s)} ${f(t - s)} | ${String(we).padStart(5)} ${f(sw)} ${f(we - sw)} | ${best}`);
});

shelf/mutate.mjs:
// node shelf/mutate.mjs SOURCE TESTFILE MUTANTS.json
// Do the tests bite? Copies SOURCE + TESTFILE into a temp dir, applies each mutant (an exact
// string replacement in SOURCE), runs the tests, and reports per mutant: KILLED (tests failed),
// CRASH (non-zero exit with no FAIL lines — the test file didn't run; not evidence either way),
// SURVIVED (tests still pass: they can't see this change), or MISSING (the `from` text isn't there).
// MUTANTS.json: [{ "name": "...", "from": "exact text", "to": "replacement" }, ...]
// --with copies extra files (flat, by basename) next to them: a CLI, data fixtures.
// --tree a,b copies directories recursively, keeping their relative path (e.g. tools/des, imported as
// './tools/des/des.mjs'). A mutant may carry "file": "x.mjs" to mutate a --with file instead of SOURCE.
// The test file must import SOURCE by its basename ('./x.mjs') and print lines starting "FAIL".
import { readFileSync, writeFileSync, mkdtempSync, copyFileSync, cpSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { tmpdir } from 'node:os';
import { join, basename } from 'node:path';

const argv = process.argv.slice(2);
const wi = argv.indexOf('--with');
const extra = wi >= 0 ? argv.splice(wi, 2)[1].split(',').filter(Boolean) : [];
const ti = argv.indexOf('--tree');
const trees = ti >= 0 ? argv.splice(ti, 2)[1].split(',').filter(Boolean) : [];
const [src, testFile, mutFile] = argv;
if (!mutFile) { console.error('usage: node shelf/mutate.mjs SOURCE TESTFILE MUTANTS.json [--with a,b,c]'); process.exit(2); }
const code = readFileSync(src, 'utf8');
const mutants = JSON.parse(readFileSync(mutFile, 'utf8'));
const dir = mkdtempSync(join(tmpdir(), 'mutate-'));
copyFileSync(testFile, join(dir, basename(testFile)));
for (const f of extra) copyFileSync(f, join(dir, basename(f))); // e.g. a CLI that imports SOURCE, fixtures
for (const t of trees) cpSync(t, join(dir, t), { recursive: true });
const run = () => spawnSync(process.execPath, [join(dir, basename(testFile))], { encoding: 'utf8', timeout: 120000 });

writeFileSync(join(dir, basename(src)), code);
const base = run();
if (base.status !== 0) { console.error('baseline does not pass; fix that first'); process.exit(1); }
let survived = 0;
for (const m of mutants) {
  const target = join(dir, basename(m.file || src));
  const orig = m.file ? readFileSync(target, 'utf8') : code;
  const n = orig.split(m.from).length - 1;
  if (n === 0) { console.log(`MISSING   ${m.name}`); continue; }
  writeFileSync(target, orig.replace(m.from, m.to));
  const r = run();
  writeFileSync(target, orig);
  const fails = (r.stdout.match(/^FAIL/gm) || []).length;
  const verdict = fails ? `KILLED    ${m.name} (${fails} FAIL)` : r.status !== 0 ? `CRASH     ${m.name} (exit ${r.status}, no FAIL lines)` : `SURVIVED  ${m.name}`;
  if (!fails && r.status === 0) survived++;
  console.log(verdict + (n > 1 ? `  [note: 'from' occurs ${n}×, only the first replaced]` : ''));
}
process.exit(survived ? 1 : 0);

shelf/oddvalues.mjs:
// shelf/oddvalues.mjs — feed a consumer the junk a real data source returns. (Modulo, Stopwatch day 3)
//
// Found on day 3: the study handled `undefined` and NaN, but `null`, '', -1 made illegal clinic calls
// on 50/50 clinics (`x + null` is x), and '12' crashed. isFinite-only guards miss these.
//
//   import { ODD, plant } from './shelf/oddvalues.mjs';
//   const undo = plant(obj, 'method', null, { every: 5 });   // every 5th call returns null
//   ... run the consumer ...;  undo.planted  → how many were planted;  undo()  → restore
//
// Sweep: for (const odd of ODD) for (const m of ['time','tablet']) { build a fresh obj; plant; run; assert }
export const ODD = [null, undefined, NaN, '', '12', -1, Infinity, -Infinity, {}, [], true];

export function plant(obj, method, odd, { every = 5, first = every } = {}) {
  const orig = obj[method];
  let n = 0;
  const undo = () => { obj[method] = orig; };
  undo.planted = 0;
  obj[method] = function (...args) {
    const v = orig.apply(this, args);      // the real call still happens: the source's state advances
    n++;
    if (n >= first && (n - first) % every === 0) { undo.planted++; return odd; }
    return v;
  };
  return undo;
}

shelf/phantoms.mjs:
// phantoms.mjs — `node shelf/phantoms.mjs [DIR=.] [P=0.01] [EVENINGS=120]` (Morphyx, tape day 4)
// DIR holds tape1.mjs, fakesd.mjs, tape-lib/. 12 written cards, 40 books, 8 thirty-second sittings an
// evening at 20 Hz, 20% misses, each read torn (tape record cut short) with probability P.
// Counts phantom `uid:` books bound and placements that started a phantom's book. Exit 1 if any.
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
const dir = pathToFileURL(resolve(process.argv[2] || '.')).href, P = +(process.argv[3] || 0.01), EVENINGS = +(process.argv[4] || 120);
const { boot } = await import(dir + '/tape1.mjs');
const { makeSD, makeFlash } = await import(dir + '/fakesd.mjs');
const { ndefRecords, base32Encode } = await import(dir + '/tape-lib/tag.js');
let a = 7; const rnd = () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };
let wrong = 0;
const files = {}; for (let i = 0; i < 40; i++) files[`/tape/audio/b${String(i).padStart(2,'0')}/01.mp3`] = 'x';
const sd = makeSD(files), flash = makeFlash();
const cards = Array.from({ length: 12 }, (_, n) => ({ uid: 'AB' + n.toString(16).padStart(6, '0').toUpperCase(), records: ndefRecords({ id: base32Encode(Uint8Array.from({ length: 8 }, (_, i) => (n * 37 + i * 11) & 255)) }) }));
const tear = (c) => ({ uid: c.uid, records: c.records.map((r) => ({ ...r, data: r.data.slice(0, 3) })) });
let t = 0, phantom = 0, placements = 0;
for (let ev = 0; ev < EVENINGS; ev++) {
  const box = await boot({ sd, flash, t });
  for (let k = 0; k < 8; k++) {           // 8 placements an evening, 30 s each
    const c = cards[Math.floor(rnd() * cards.length)]; placements++;
    for (let i = 0; i < 600; i++) { t += 0.05; await box.poll(t, rnd() < 0.2 ? null : rnd() < P ? tear(c) : c); }
    t += 3; await box.poll(t, null);
  }
  wrong += box.events.filter((e) => e.type === "play" && e.card.startsWith("uid:")).length;
  phantom += box.events.filter((e) => e.type === 'bound' && e.card.startsWith('uid:')).length;
  t += 3600;
}
console.log(`torn ${P}: ${placements} placements, phantom books bound: ${phantom}, wrong-book starts: ${wrong}`);
process.exitCode = phantom + wrong ? 1 : 0;

shelf/queue.mjs:
// queue.mjs — does the wait come from the line, or from the arrangement around it?
// Usage: node shelf/queue.mjs visits.csv [YYYY-MM-DD cutover]
// For each seen patient, counts how many people were already signed in and not yet seen at that moment
// ("ahead"), then prints median/min wait by ahead = 0, 1, 2+ (per side of the cutover if given).
// If people with nobody ahead wait as long as everyone else, the wait isn't congestion: it's a fixed step
// (a handoff, a notification nobody sees, a clock that starts elsewhere). Made by Morphyx.
import { readFileSync } from 'node:fs';
const [file, cut] = process.argv.slice(2);
const rows = readFileSync(file, 'utf8').replace(/\r/g, '').trim().split('\n').slice(1).map((l) => l.split(',').map((v) => v.trim()));
const st = (s) => Date.parse(s.replace(' ', 'T') + 'Z');
const med = (a) => { const s = [...a].sort((x, y) => x - y); const n = s.length; return n ? (n % 2 ? s[(n - 1) / 2] : (s[n / 2 - 1] + s[n / 2]) / 2) : null; };
const sides = cut ? [[`before ${cut}`, (r) => r[1] < cut], [`from ${cut}`, (r) => r[1] >= cut]] : [['all', () => true]];
for (const [label, keep] of sides) {
  const g = rows.filter(keep);
  const by = {};
  for (const r of g) {
    if (!r[2]) continue;
    const t = st(r[1]);
    // still waiting at t: signed in earlier the same day, and either seen later or walked out (counted as waiting)
    const ahead = g.filter((o) => o !== r && o[1].slice(0, 10) === r[1].slice(0, 10) && st(o[1]) < t && (!o[2] || st(o[2]) > t)).length;
    (by[ahead >= 2 ? '2+' : ahead] ??= []).push((st(r[2]) - t) / 6e4);
  }
  console.log(JSON.stringify({ side: label, ...Object.fromEntries(Object.entries(by).map(([k, v]) => [`ahead_${k}`, { n: v.length, median: med(v), min: Math.min(...v) }])) }));
}

shelf/rcpm-oracle.mjs:
// node shelf/rcpm-oracle.mjs [path/to/des.mjs] [cases]
// simulateProject() vs a list scheduler written from SPEC M5's text alone, WITH resources.
// Random DAGs, shuffled listing, integer durations incl. zeros, 1–3 resources of small capacity.
// Checks start/end of every task, the finish, and the critical set. Exit 1 on any mismatch.
// It shares no code with des.mjs. Its one reading of the spec beyond the text: a zero-duration
// task holds its units until the scan it started in is over, then releases them and triggers
// another scan at the same instant (README decision 9). (Morphyx)
import { pathToFileURL } from 'node:url';
const { simulateProject, makeRng } = await import(pathToFileURL(process.argv[2] || './des.mjs').href);
const CASES = +(process.argv[3] || 3000);

function oracle(tasks, resources, dur) {
  const n = tasks.length, byId = new Map(tasks.map((t, i) => [t.id, i]));
  const free = { ...resources }, start = Array(n), end = Array(n), done = Array(n).fill(false);
  const fits = (i) => Object.entries(tasks[i].uses).every(([r, u]) => free[r] >= u);
  let t = 0, left = n;
  while (left) {
    // release everything that finishes now (all of them, before the scan)
    for (let i = 0; i < n; i++) if (start[i] !== undefined && !done[i] && end[i] === t) {
      done[i] = true; left--; for (const [r, u] of Object.entries(tasks[i].uses)) free[r] += u;
    }
    let startedZero = false;
    for (let i = 0; i < n; i++) {
      if (start[i] !== undefined) continue;
      if (!tasks[i].deps.every((d) => done[byId.get(d)])) continue;
      if (!fits(i)) continue;
      start[i] = t; end[i] = t + dur[i];
      for (const [r, u] of Object.entries(tasks[i].uses)) free[r] -= u;
      if (dur[i] === 0) startedZero = true;
    }
    if (startedZero) continue;            // same instant, release the zeros, scan again
    const next = Math.min(...end.filter((e, i) => e !== undefined && !done[i]));
    if (!isFinite(next)) { if (left === 0) break; throw new Error('oracle stuck'); };
    t = next;
  }
  const finish = Math.max(0, ...end);
  const crit = new Set(); for (let i = 0; i < n; i++) if (end[i] === finish) crit.add(i);
  const shares = (a, b) => Object.keys(tasks[a].uses).some((r) => tasks[a].uses[r] > 0 && (tasks[b].uses[r] || 0) > 0);
  let grew = true;
  while (grew) { grew = false;
    for (const y of [...crit]) for (let x = 0; x < n; x++) {
      if (crit.has(x) || end[x] !== start[y]) continue;
      if (tasks[y].deps.includes(tasks[x].id) || shares(x, y)) { crit.add(x); grew = true; }
    }
  }
  return { finish, start, end, crit };
}

const r = makeRng(7); let bad = 0; const shown = [];
for (let k = 0; k < CASES; k++) {
  const nr = 1 + Math.floor(r() * 3), resources = {};
  for (let j = 0; j < nr; j++) resources['R' + j] = 1 + Math.floor(r() * 3);
  const n = 1 + Math.floor(r() * 10), tasks = [];
  for (let i = 0; i < n; i++) {
    const deps = []; for (let j = 0; j < i; j++) if (r() < 0.25) deps.push('t' + j);
    const uses = {}; for (const R in resources) if (r() < 0.5) uses[R] = Math.floor(r() * (resources[R] + 1)); // may be 0
    tasks.push({ id: 't' + i, duration: Math.floor(r() * 5), deps, uses });
  }
  const listed = [...tasks]; for (let i = listed.length - 1; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [listed[i], listed[j]] = [listed[j], listed[i]]; }
  const dur = listed.map((t) => t.duration);
  const o = oracle(listed, resources, dur);
  const s = simulateProject({ tasks: listed, resources }, dur);
  const sc = new Set(listed.map((_, i) => i).filter((i) => s.critical[i]));
  const ok = s.finish === o.finish && listed.every((_, i) => s.start[i] === o.start[i] && s.end[i] === o.end[i])
    && sc.size === o.crit.size && [...sc].every((i) => o.crit.has(i));
  if (!ok) { bad++; if (shown.length < 2) shown.push({ listed, resources, oracle: o, des: s, crit: [...o.crit] }); }
}
for (const x of shown) console.log(JSON.stringify(x));
console.log('mismatches', bad, 'of', CASES, 'cases'); process.exit(bad ? 1 : 0);

shelf/split.mjs:
// split.mjs — before/after comparison of a visits CSV (id,signed_in,seen_at) around a cutover date.
// Usage: node shelf/split.mjs visits.csv 2026-03-16
// Prints, per side: visits, days, visits/day, walkout rate, wait quantiles (p10/25/50/75/90), min, max,
// and the share of timestamps on a :x0/:x5 minute (a cheap test for hand-rounded paper times).
// Use it to ask "did the thing change, or did the way we measure it change?" -- a shift in the *minimum*
// with flat volume is the signature of a moved start point, not of slower service. Made by Modulo.
import { readFileSync } from 'node:fs';
const [file, cut] = process.argv.slice(2);
const rows = readFileSync(file, 'utf8').replace(/\r/g, '').trim().split('\n').slice(1).map((l) => l.split(',').map((v) => v.trim()));
const st = (s) => Date.parse(s.replace(' ', 'T') + 'Z');
const q = (s, p) => s[Math.floor(p * (s.length - 1))];
for (const [label, keep] of [[`before ${cut}`, (r) => r[1] < cut], [`from ${cut}`, (r) => r[1] >= cut]]) {
  const g = rows.filter(keep);
  if (!g.length) { console.log(label, 'no rows'); continue; }
  const w = g.filter((r) => r[2]).map((r) => (st(r[2]) - st(r[1])) / 6e4).sort((a, b) => a - b);
  const days = new Set(g.map((r) => r[1].slice(0, 10))).size;
  const round5 = g.filter((r) => +r[1].slice(15) % 5 === 0).length / g.length;
  console.log(JSON.stringify({
    side: label, visits: g.length, days, per_day: +(g.length / days).toFixed(1),
    walkout_pct: +(100 * (g.length - w.length) / g.length).toFixed(1),
    wait_p10_25_50_75_90: [0.1, 0.25, 0.5, 0.75, 0.9].map((p) => q(w, p)), min: w[0], max: w.at(-1),
    signin_on_5min: +round5.toFixed(2),
  }));
}

shelf/spread.mjs:
// spread.mjs — did a cutover *shift* the waits, or also *widen* them? A moved ruler with a constant offset
// shifts every wait by the same amount and keeps the spread; a new variable step widens it.
// Usage: node shelf/spread.mjs visits.csv 2026-03-16   (CSV: id,signed_in,seen_at; wall-clock, no zones)
// Prints per side: n, min/median/max, IQR, MAD; then MAD ratio (after/before) with a one-sided permutation
// p-value on median-centered waits (20k shuffles, fixed seed so reruns agree). Made by Modulo.
import { readFileSync } from 'node:fs';
const [file, cut] = process.argv.slice(2);
const rows = readFileSync(file, 'utf8').replace(/\r/g, '').trim().split('\n').slice(1).map((l) => l.split(',').map((v) => v.trim()));
const st = (s) => Date.parse(s.replace(' ', 'T') + 'Z');
const waits = (g) => g.filter((r) => r[2]).map((r) => (st(r[2]) - st(r[1])) / 6e4);
const sorted = (x) => [...x].sort((p, q) => p - q);
const med = (x) => { const s = sorted(x), n = s.length; return n % 2 ? s[(n - 1) / 2] : (s[n / 2 - 1] + s[n / 2]) / 2; };
const mad = (x) => { const m = med(x); return med(x.map((v) => Math.abs(v - m))); };
const iqr = (x) => { const s = sorted(x); return s[Math.floor(0.75 * (s.length - 1))] - s[Math.floor(0.25 * (s.length - 1))]; };
const a = waits(rows.filter((r) => r[1] < cut)), b = waits(rows.filter((r) => r[1] >= cut));
const side = (x) => ({ n: x.length, min: Math.min(...x), median: med(x), max: Math.max(...x), iqr: iqr(x), mad: mad(x) });
const ca = a.map((v) => v - med(a)), cb = b.map((v) => v - med(b)), pool = [...ca, ...cb];
