  const reqs = genReqs(true), checks = Array.from({ length: ri(1, 8) }, (_, i) => 'C-' + i);
  const links = Array.from({ length: ri(0, 20) }, () => ({
    from: rnd() < 0.8 ? pick(checks) : 'art' + ri(0, 2), to: rnd() < 0.9 ? pick(reqs).id : 'MISSING',
    kind: rnd() < 0.7 ? 'verifies' : 'implements',
