for (let c = 0; c < CASES; c++) {
  const list = genReqs(rnd() < 0.3);
  cmp('load', list, oLoad(list), run(() => vv.load(list).problems));
  for (const r of list) cmp('lint', r, oLint(r), run(() => vv.lint(r)));
